/** Explicit FDA destinations for exact Vault versions; the existing exporter writes them. */
import React from 'react';
import { isCanonicalId } from '@shared/regulatory/canonical-document';
import { useLiveData } from '../../v2/dataConnect';
import { VaultVersionPicker, type PickedVaultVersion } from '../../v2/surfaces/VaultLibraryResults';
import type { OfficialEstarType, OfficialEstarVariant } from '../hooks/useEstarOfficialFields';
import type { OfficialEstarAttachment, EstarAttachmentReceipt, EstarAttachmentRefusal } from '../hooks/useEstarExport';

interface AttachmentSlot {
  somPath: string;
  field: string;
  description: string | null;
  chapters: string[];
  singleAttachment: string | null;
}
interface SlotCatalog {
  descriptorId: string;
  type: string;
  variant: string;
  templateVersion: string;
  slots: AttachmentSlot[];
}
interface AttachmentRow { key: number; slot: string; document: PickedVaultVersion | null; error: string | null }
const object = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
const text = (v: unknown): v is string => typeof v === 'string' && !!v.trim();
const nullableText = (v: unknown): v is string | null => v === null || typeof v === 'string';
function isSlot(v: unknown): v is AttachmentSlot {
  return object(v) && text(v.somPath) && text(v.field) && nullableText(v.description) &&
    Array.isArray(v.chapters) && v.chapters.every(text) && nullableText(v.singleAttachment);
}
function isCatalog(v: unknown, type: string, variant: string): v is SlotCatalog {
  return object(v) && text(v.descriptorId) && v.type === type && v.variant === variant && text(v.templateVersion) &&
    Array.isArray(v.slots) && v.slots.every(isSlot) && new Set(v.slots.map(s => s.somPath)).size === v.slots.length;
}
const marketingType = (type: OfficialEstarType) => type === '510k' || type === 'de_novo' || type === 'pma';
const sourceProblem = 'Choose a current Vault version with a valid document id and recorded SHA-256.';
function validSource(document: PickedVaultVersion, programId: string | null): boolean {
  return isCanonicalId(document.id) && document.current === true && document.programId.toLowerCase() === programId?.toLowerCase() &&
    typeof document.contentHash === 'string' && /^[a-f0-9]{64}$/.test(document.contentHash);
}
function rowProblem(rows: AttachmentRow[], catalog: SlotCatalog): string | null {
  const seen = new Set<string>();
  for (const row of rows) {
    const slot = catalog.slots.find(s => s.somPath === row.slot);
    if (!slot || !row.document) return 'Choose an FDA destination and a Vault version for every attachment, or remove the incomplete row.';
    if (slot.singleAttachment && rows.filter(r => r.slot === row.slot).length > 1) return slot.singleAttachment;
    const key = `${row.slot}\0${row.document.id.toLowerCase()}`;
    if (seen.has(key)) return 'The same Vault version is selected more than once for this destination. Remove the duplicate attachment.';
    seen.add(key);
  }
  return null;
}

export function useOfficialEstarAttachments(programId: string | null, type: OfficialEstarType, variant: OfficialEstarVariant) {
  const [rows, setRows] = React.useState<AttachmentRow[]>([]);
  const next = React.useRef(0);
  const [attempt, setAttempt] = React.useState(0);
  const enabled = marketingType(type) && !!programId && isCanonicalId(programId);
  const path = enabled && rows.length ? `/api/510k/estar/attachment-slots?${new URLSearchParams({ type, variant })}` : null;
  const read = useLiveData<SlotCatalog>(path, [path, attempt], (value): value is SlotCatalog => isCatalog(value, type, variant));
  const catalog = read.loading || read.error ? null : read.data;
  const loading = !!path && (read.loading || (!read.error && !read.data));
  let problem: string | null = null;
  if (rows.length) {
    if (!enabled) problem = 'Open a regulatory program before choosing Vault attachments.';
    else if (loading) problem = 'Reading FDA attachment destinations…';
    else if (!catalog) problem = 'Attachment destinations could not be read. Retry them or remove the attachment rows.';
    else if (!catalog.slots.length) problem = 'This template has no attachment destinations. Remove the attachment rows to generate without them.';
    else problem = rowProblem(rows, catalog);
  }
  const requests: OfficialEstarAttachment[] = problem ? [] : rows.flatMap(row => row.document?.contentHash ? [{
    slot: row.slot, source: { kind: 'vault_document' as const, documentId: row.document.id }, expectedSha256: row.document.contentHash,
  }] : []);
  const patch = (key: number, change: Partial<AttachmentRow>) => setRows(previous => previous.map(row => row.key === key ? { ...row, ...change } : row));
  return {
    rows, enabled, loading, catalog, problem, requests,
    failed: !!path && !loading && !catalog,
    retry: () => setAttempt(value => value + 1),
    add: () => { if (enabled) setRows(previous => [...previous, { key: ++next.current, slot: '', document: null, error: null }]); },
    remove: (key: number) => setRows(previous => previous.filter(row => row.key !== key)),
    slot: (key: number, slot: string) => patch(key, { slot }),
    change: (key: number) => patch(key, { document: null, error: null }),
    choose: (key: number, document: PickedVaultVersion) => patch(key, validSource(document, programId)
      ? { document, error: null } : { document: null, error: sourceProblem }),
  };
}
type AttachmentPlan = ReturnType<typeof useOfficialEstarAttachments>;
const buttonStyle: React.CSSProperties = { minHeight: 44 };
const labelOf = (slot: AttachmentSlot) => `${slot.description || slot.field}${slot.chapters.length ? ` · ${slot.chapters.join(' · ')}` : ''}`;

function AttachmentRowFields({ row, index, plan, programId, busy }: {
  row: AttachmentRow; index: number; plan: AttachmentPlan; programId: string; busy: boolean;
}) {
  const id = React.useId();
  return <fieldset disabled={busy} style={{ border: 0, borderTop: '1px solid var(--border)', margin: '12px 0 0', padding: '12px 0 0', minWidth: 0 }}>
    <legend className="section-sub">Attachment {index + 1}</legend>
    <label htmlFor={id} className="section-sub" style={{ display: 'block', marginBottom: 6 }}>FDA destination</label>
    <select id={id} className="c2c-input" value={row.slot} disabled={busy || !plan.catalog}
      style={{ width: '100%', minWidth: 0, minHeight: 44 }} onChange={event => plan.slot(row.key, event.target.value)}>
      <option value="">Choose an FDA destination…</option>
      {plan.catalog?.slots.map(slot => <option value={slot.somPath} key={slot.somPath}>{labelOf(slot)}</option>)}
    </select>
    <div style={{ marginTop: 10, minWidth: 0, overflowWrap: 'anywhere' }}>
      {row.document ? <div className="section-sub">
        <strong>{row.document.title}</strong>
        <div>Version {row.document.version || 'not recorded'} · current</div>
        <div>SHA-256 {row.document.contentHash}</div>
        <button type="button" className="btn ghost small" style={buttonStyle} disabled={busy} onClick={() => plan.change(row.key)}>Change document</button>
      </div> : <>
        <p className="section-sub">Search this project’s Vault to choose a version. The server checks current approval and access again when generating.</p>
        <VaultVersionPicker programId={programId} disabled={busy} label="Search this project's Vault" onChoose={document => plan.choose(row.key, document)} />
      </>}
    </div>
    {row.error && <p role="alert" aria-live="assertive" className="section-sub">{row.error}</p>}
    <button type="button" className="btn ghost small" style={buttonStyle} disabled={busy} onClick={() => plan.remove(row.key)}>Remove attachment</button>
  </fieldset>;
}

export function OfficialEstarAttachments({ plan, programId, busy }: { plan: AttachmentPlan; programId: string | null; busy: boolean }) {
  return <section className="panel" style={{ marginTop: 8, padding: 12, minWidth: 0 }} data-testid="official-estar-attachments" aria-label="Vault attachments">
    <div className="section-sub">Optional Vault attachments. Choose each FDA destination explicitly; earlier files and exports stay unchanged.</div>
    {!plan.rows.length && <p className="section-sub">No Vault attachments selected.</p>}
    {plan.loading && <p className="section-sub" role="status" aria-live="polite" aria-busy="true">Reading FDA attachment destinations…</p>}
    {plan.failed && <div role="alert" aria-live="assertive" className="section-sub">
      Attachment destinations could not be read. This is not an empty list.
      <button type="button" className="btn ghost small" style={buttonStyle} disabled={busy} onClick={plan.retry}>Retry attachment destinations</button>
    </div>}
    {plan.catalog && plan.rows.length > 0 && <p className="section-sub">FDA template {plan.catalog.templateVersion}. Only current, approved versions can be attached.</p>}
    {programId && plan.enabled && plan.rows.map((row, index) => <AttachmentRowFields key={row.key} {...{ row, index, plan, programId, busy }} />)}
    {plan.problem && !plan.loading && !plan.failed && <p role="status" aria-live="polite" className="section-sub">{plan.problem}</p>}
    <button type="button" className="btn ghost small" style={buttonStyle} disabled={busy || !plan.enabled} onClick={plan.add}>Add Vault attachment</button>
    {!plan.enabled && <p className="section-sub" role="status">Open a regulatory program to choose its Vault versions.</p>}
  </section>;
}

export function OfficialEstarAttachmentOutcome({ attachments, refusals, catalog }: {
  attachments?: EstarAttachmentReceipt[]; refusals?: EstarAttachmentRefusal[]; catalog: SlotCatalog | null;
}) {
  const destination = (path: string) => { const slot = catalog?.slots.find(slot => slot.somPath === path); return slot ? slot.description || slot.field : 'Selected FDA destination'; };
  return <>
    {!!attachments?.length && <div className="section-sub" role="status" style={{ marginTop: 8, overflowWrap: 'anywhere' }} data-testid="official-estar-attachment-receipts">
      Attached files confirmed by the server:
      <ul>{attachments.map((attachment, i) => <li key={`${attachment.slot}:${attachment.source.documentId}:${i}`}>
        <strong>{attachment.fileName}</strong> · {destination(attachment.slot)} · {attachment.chapter}
        <div>{attachment.byteLength} bytes · SHA-256 {attachment.sha256}</div>
      </li>)}</ul>
    </div>}
    {!!refusals?.length && <div className="section-sub" role="alert" aria-live="assertive" style={{ marginTop: 8 }} data-testid="official-estar-attachment-refusals">
      Attachment export refused:
      <ul>{refusals.map((refusal, i) => <li key={`${refusal.slot}:${i}`}>{destination(refusal.slot)}: {refusal.reasons.join(' · ')}</li>)}</ul>
    </div>}
  </>;
}

/**
 * OfficialEstarPanel — the ONE place the official FDA eSTAR PDF is produced
 * from, and the surface that says exactly what will be written into it.
 *
 * Three reads, one governed action:
 *   useEstarReadiness        can the descriptor be produced at all (template
 *                            vendored, field map populated)? Drives the
 *                            produce-gate: locked with the reason, never dead.
 *   useEstarOfficialFields   the "what will be written" preview — one row per
 *                            mapped field with the governed value and its
 *                            source in plain words. Unsourced keys get an input
 *                            the user may fill for this export only.
 *   useEstarExport           POST /official with useProgramData:true and only
 *                            the values actually typed. The response's
 *                            fieldReport is rendered as filled/blank counts,
 *                            the blank captions and any typed keys the server
 *                            dropped.
 *
 * Honest by construction: a failed field read renders ErrorState with the
 * reason in plain words, never an empty table — and offers retry only when a
 * retry could succeed (a 404 or 422 is not transient); a value the platform
 * does not hold is shown as blank and reported after the run, never guessed;
 * nothing typed here is stored. Entitlement lock mirrors K510Surface — a 403
 * NOT_ENTITLED shows the Locked pill and the real minimum tier in the
 * control's title.
 *
 * Two useFetchJson facts shape the render: it keeps the PREVIOUS payload in
 * `data` across a url change (only `loading` flips), and it starts loading:false
 * until its effect runs. So an in-flight field read is treated as "no field
 * list" — never another program's rows under this program's header — and a
 * readiness read with neither an answer nor an error is "checking", never
 * "not producible".
 */

import * as React from 'react';
import { EmptyState, ErrorState } from '../../v2/dataConnect';
import { I } from '../icons';
import type { Program } from '../data/programs';
import { useSubmissionReadSession } from '../../v2/surfaces/submissionScopedRead';
import { OfficialEstarAttachments, OfficialEstarAttachmentOutcome, useOfficialEstarAttachments } from './OfficialEstarAttachments';
import { useEstarReadiness } from '../hooks/useK510';
import {
  notSetWords,
  sourceWords,
  useEstarOfficialFields,
  type OfficialEstarType,
  type OfficialEstarVariant,
  type OfficialFieldView,
} from '../hooks/useEstarOfficialFields';
import {
  entitlementBlocksExport,
  entitlementRequiredLine,
  exportStatusLine,
  useEstarEntitlement,
  useEstarExport,
  type ProgramRef,
} from '../hooks/useEstarExport';

/** The FDA template family a variant is produced on, in FDA's own words. */
export const ESTAR_FAMILY_WORDS: Record<OfficialEstarVariant, string> = {
  device: 'nIVD eSTAR',
  ivd: 'IVD eSTAR',
};

/** The marketing pathway a type is produced for, in FDA's own words. */
export const ESTAR_PATHWAY_WORDS: Record<OfficialEstarType, string> = {
  '510k': '510(k)',
  de_novo: 'De Novo',
  pma: 'PMA',
  q_sub: 'Q-Submission',
  ide: 'IDE',
  '513g': '513(g)',
};

/**
 * Which marketing pathway a program files on. The kit folds De Novo into the
 * k510 pathway (both share the 510(k) surface), so the raw regulatory path is
 * what decides: 'de_novo' and 'pma' name themselves; anything else — '510k',
 * an unset path, the kit's sample rows — reads as a 510(k). Never guessed from
 * the surface, which is why a PMA row on the PMA surface and a De Novo row on
 * the 510(k) surface both produce the pathway they hold.
 */
export function officialEstarTypeFor(
  program: Pick<Program, 'regulatoryPath'> | null | undefined,
): OfficialEstarType {
  const path = (program?.regulatoryPath ?? '').toLowerCase();
  if (path === 'de_novo') return 'de_novo';
  if (path === 'pma') return 'pma';
  return '510k';
}

/**
 * Which official template a program files on. An IVD program that files a
 * 510(k) reaches the 510(k) surface (its pathway is k510), so the variant is
 * decided by the program's product type, never by the surface it is on.
 * Absent product type (the kit's sample rows) reads as a device.
 */
export function officialEstarVariantFor(
  program: Pick<Program, 'productType'> | null | undefined,
): OfficialEstarVariant {
  return (program?.productType ?? '').toLowerCase() === 'ivd' ? 'ivd' : 'device';
}

/** The disabled-control title for a plan that does not unlock the export. */
export function entitlementLockTitle(requiredTier: string | null | undefined): string {
  return requiredTier
    ? `Locked — requires the ${requiredTier} plan (device assembly readiness)`
    : 'Locked — requires a higher plan (device assembly readiness)';
}

export interface OfficialEstarPanelProps {
  program: ProgramRef | null;
  variant: OfficialEstarVariant;
  type?: OfficialEstarType;
}

const fieldInputStyle: React.CSSProperties = {
  width: '100%',
  fontSize: 12,
  padding: '5px 8px',
  background: 'var(--bg-050)',
  border: '1px solid var(--border-100)',
  borderRadius: 6,
  color: 'var(--text-200)',
};

/**
 * The reason the Generate control is disabled, or null when it may fire. Pure
 * so the precedence (lock → no program → readiness checking → busy → not ready
 * → field list failed) is pinned by a test. The last step exists because a
 * readiness 200 next to a failed field read would otherwise leave Generate
 * live while the user has not seen what will be written.
 */
export function generateDisabledReason(input: {
  lockedTitle: string | null;
  hasProgram: boolean;
  readinessLoading: boolean;
  readinessError: string | null;
  ready: boolean;
  blockers: string[];
  busy: boolean;
  fieldsError: string | null;
}): string | null {
  if (input.lockedTitle) return input.lockedTitle;
  if (!input.hasProgram) return 'Open a program first — the administrative data is read from it';
  if (input.readinessLoading) return 'Checking official eSTAR availability…';
  if (input.busy) return 'Exporting…';
  if (!input.ready) {
    const why = input.blockers.length
      ? input.blockers.join(' · ')
      : input.readinessError
        ? 'availability could not be checked'
        : 'the official template or its field map is not available';
    return `Official eSTAR not yet producible — ${why}`;
  }
  if (input.fieldsError) return 'The field list could not be loaded — load it before generating';
  return null;
}

function captionOf(fields: OfficialFieldView[] | undefined, key: string): string {
  return fields?.find((f) => f.key === key)?.caption ?? key;
}

export function OfficialEstarPanel({ program, variant, type = '510k' }: OfficialEstarPanelProps) {
  const session = useSubmissionReadSession();
  const context = JSON.stringify([program?.id, type, variant, session.key]);
  const visit = React.useRef({ context });
  if (visit.current.context !== context) visit.current = { context };
  const captured = visit.current;
  const current = () => visit.current === captured && session.sameRevision();
  return <OfficialEstarPanelForContext key={context} {...{ program, variant, type, current }} />;
}

function OfficialEstarPanelForContext({ program, variant, type = '510k', current }: OfficialEstarPanelProps & { current: () => boolean }) {
  const prestar = type === 'q_sub' || type === 'ide' || type === '513g';
  const ident = program?.id ?? null;
  const readiness = useEstarReadiness(type, variant);
  const official = useEstarOfficialFields(ident, type, variant);
  const estarExport = useEstarExport(current);
  const entitlement = useEstarEntitlement();
  const attachments = useOfficialEstarAttachments(ident, type, variant);

  /* Values typed for THIS export only. Re-seeded empty on a program or variant
     switch so nothing typed under one device travels to the next — and the last
     export outcome is forgotten with them, so a previous program's
     "Downloaded … filled/blank" line and blank-caption list never sit under
     this program's header (the same rule the field list follows below). */
  const [typed, setTyped] = React.useState<Record<string, string>>({});
  const resetExport = estarExport.reset;
  React.useEffect(() => {
    setTyped({});
    resetExport();
  }, [ident, type, variant, resetExport]);

  const ready = readiness.readiness?.ready === true;
  const blockers = readiness.readiness?.blockers ?? [];
  /* useFetchJson reports loading:false until its effect runs, so the first
     painted frame has neither an answer nor an error. That is "not checked
     yet" — asserting "not producible" there would be a claim nothing made. */
  const readinessChecking =
    readiness.loading || (readiness.readiness === null && readiness.error === null);

  /* An in-flight field read is neither a list nor an error: useFetchJson keeps
     the previous program's payload in `data` while the next one loads, and a
     refresh after a failure keeps the old error until the retry settles. */
  const fields = official.loading ? null : official.fields;
  const fieldsError = official.loading ? null : official.error;

  /* Locked-never-dead (entitlements contract §4) — the same shape K510Surface
     uses for the draft package: only the entitlement gate's exact 403 sets
     blockedByEntitlement, so a role 403 never reads as a plan limitation. */
  /* …and the lock is known BEFORE the first click: the entitlement read says
     whether the producing route would refuse today. Only an ENFORCED denial
     locks — in warn/off mode the POST goes through, so locking on it would be
     a claim the server does not make. A failed read locks nothing; the 403
     path still guards the write. */
  const refusedAfterClick = estarExport.outcome?.blockedByEntitlement === true;
  const lockedBeforeClick = entitlementBlocksExport(entitlement.entitlement);
  const entitlementLocked = refusedAfterClick || lockedBeforeClick;
  const lockedTier = refusedAfterClick
    ? estarExport.outcome?.requiredTier ?? null
    : entitlement.entitlement?.requiredTier ?? null;
  const lockedTitle = entitlementLocked ? entitlementLockTitle(lockedTier) : null;

  const disabledReason = generateDisabledReason({
    lockedTitle,
    hasProgram: !!program,
    readinessLoading: readinessChecking,
    readinessError: readiness.error,
    ready,
    blockers,
    busy: estarExport.busy,
    fieldsError,
  }) ?? attachments.problem;

  const headerLine = !program
    ? 'The administrative data is read from the open program'
    : official.loading
      ? 'Loading the field list…'
      : fieldsError
        ? 'The field list could not be loaded'
        : fields
          ? `${fields.sourcedCount} of ${fields.mappedCount} fields have a governed source`
          : 'No field list yet';

  const exportStatus = exportStatusLine(estarExport.busy, estarExport.outcome);
  const report = estarExport.outcome?.ok ? estarExport.outcome.fieldReport : null;

  function onGenerate() {
    if (!program || disabledReason || !current()) return;
    void estarExport.exportOfficialEstar(
      { id: program.id, code: program.code, title: program.title },
      variant,
      { type, useProgramData: true, data: typed, ...(attachments.requests.length ? { attachments: attachments.requests } : {}) },
    );
  }

  return (
    <>
      <div className="section-hdr">
        <div>
          <div className="section-title">
            {prestar ? 'PreSTAR administrative prefill' : 'Official eSTAR'} · {ESTAR_PATHWAY_WORDS[type]} · {prestar ? 'PreSTAR' : ESTAR_FAMILY_WORDS[variant]}
          </div>
          <div className="section-sub">{headerLine}</div>
        </div>
        <button
          className="section-more"
          disabled={disabledReason !== null}
          title={
            disabledReason ??
            'Produce the official FDA eSTAR PDF from the program’s governed records and the values entered below'
          }
          onClick={onGenerate}
        >
          {prestar ? 'Prepare PreSTAR fields (PDF)' : 'Generate official eSTAR (PDF)'} {I.download}
        </button>
      </div>

      {prestar && <p className="section-sub" role="status" data-testid="prestar-completion-required">
        Four administrative fields can be prepared from this program’s records. Choose the request type and complete its questions and declarations in a compatible PDF editor. This prefill does not establish filing readiness or agency acceptance.
      </p>}

      {readinessChecking && program ? (
        <div className="section-sub" role="status" style={{ marginTop: 4 }}>
          Checking official eSTAR availability…
        </div>
      ) : null}

      {!readinessChecking && !ready && program ? (
        <div className="section-sub" role="status" style={{ marginTop: 4 }}>
          <span className="status-pill review">Not yet producible</span>{' '}
          {blockers.length
            ? blockers.join(' · ')
            : readiness.error
              ? 'Official eSTAR availability could not be checked'
              : 'The official template or its field map is not available'}
        </div>
      ) : null}

      {lockedBeforeClick && !exportStatus ? (
        <div className="section-sub" role="status" style={{ marginTop: 4 }} data-testid="official-estar-locked">
          <span className="status-pill review" style={{ marginRight: 6 }}>
            Locked
          </span>
          {entitlementRequiredLine(lockedTier)}
        </div>
      ) : null}

      {exportStatus ? (
        <div className="section-sub" role="status" style={{ marginTop: 4 }}>
          {entitlementLocked ? (
            <span className="status-pill review" style={{ marginRight: 6 }}>
              Locked
            </span>
          ) : null}
          {exportStatus}
        </div>
      ) : null}

      {report ? (
        <div className="section-sub" role="status" style={{ marginTop: 4 }}>
          {/* FDA ships the eSTAR with its administrative sections
              presence="hidden"; the form's own script reveals them once the
              applicant picks the submission type. The values are written and
              bound either way (an independent XFA engine renders all of them
              once those sections are visible), but a reader who opens the file
              and sees a first page only would otherwise think it came out
              blank. Stating it is the difference between a filed form and a
              support ticket. */}
          <div data-testid="official-estar-open-note">
            Open the file in Adobe Acrobat and choose the submission type on the first page. The
            administrative sections stay hidden until the form reveals them.
          </div>
          {report.blankKeys.length ? (
            <div>
              Left blank — the platform holds no value:{' '}
              {report.blankKeys.map((k) => captionOf(fields?.fields, k)).join(' · ')}
            </div>
          ) : null}
          {report.ignoredRequestKeys.length ? (
            <div>
              Entered values not written — a governed value took precedence or the field is not
              on the template: {report.ignoredRequestKeys.map((k) => captionOf(fields?.fields, k)).join(' · ')}
            </div>
          ) : null}
          {/*
            These two lines are the other half of the note above. Choosing the
            submission type is what reveals the sections — and the same scripts
            that reveal them recompute several of these cells from source fields
            elsewhere on the form. We measured which, per field, against the
            vendored template (ESTAR_TEMPLATE_RECOMPUTED_FIELDS); until now that
            record went no further than a unit test, so the panel reported those
            cells filled and said nothing about what happens next. A filer who
            follows the instruction directly above would watch them empty.
          */}
          {report.clearedByTemplateKeys.length ? (
            <div data-testid="official-estar-cleared-note">
              Written, but the form clears these when you choose the submission type or edit the
              control they come from — re-enter them on the form:{' '}
              {report.clearedByTemplateKeys.map((k) => captionOf(fields?.fields, k)).join(' · ')}
            </div>
          ) : null}
          {report.substitutedByTemplateKeys.length ? (
            <div data-testid="official-estar-substituted-note">
              The form rebuilds these from the applicant details rather than keeping what we
              wrote, so they can end up naming a different entity — check them before signing:{' '}
              {report.substitutedByTemplateKeys.map((k) => captionOf(fields?.fields, k)).join(' · ')}
            </div>
          ) : null}
        </div>
      ) : null}

      {!prestar && <OfficialEstarAttachments plan={attachments} programId={ident} busy={estarExport.busy} />}
      <OfficialEstarAttachmentOutcome catalog={attachments.catalog}
        attachments={estarExport.outcome?.ok ? estarExport.outcome.attachments : undefined}
        refusals={estarExport.outcome?.attachmentRefusals} />

      <div className="panel" style={{ marginTop: 8 }}>
        <div className="panel-hdr">
          <div>
            <div className="t">Fields the template carries</div>
            <div className="s">
              Governed values are read-only and written as held. A value entered here is written
              to this export only and is not stored.
            </div>
          </div>
        </div>

        {!program ? (
          <EmptyState
            icon={I.circle}
            title="No program open"
            hint="The field list is held per program."
            regulation="Serves the FDA eSTAR administrative record (21 CFR 807)"
            testId="official-estar-idle"
          />
        ) : fieldsError ? (
          <ErrorState
            variant="panel"
            title="Could not load the field list"
            message={fieldsError}
            /* A 404 or 422 is not transient — offering "Try again" there is a
               promise the retry cannot keep. Only a failed read gets one. */
            retry={official.errorKind === 'failed' ? official.refresh : undefined}
            testId="official-estar-error"
          />
        ) : !fields ? (
          <EmptyState
            icon={I.database}
            busy
            title="Loading the field list"
            testId="official-estar-loading"
          />
        ) : (
          <table className="tbl">
            <thead>
              <tr>
                <th>Field</th>
                <th>Value</th>
                <th>Source</th>
              </tr>
            </thead>
            <tbody>
              {fields.fields.map((f) => {
                const sourced = f.source !== null && f.value !== null;
                /* A governed key the platform holds no value for: name the
                   durable home so the user sets it there once, and still
                   offer the export-only input so this export is not blocked
                   on it. Null when the key has no declared home — the row
                   then reads as export-only, as before. */
                const notSet = sourced ? null : notSetWords(f.declaredSource);
                const inputId = `official-estar-${variant}-${f.key}`;
                return (
                  <tr
                    key={f.key}
                    data-sourced={sourced ? 'true' : 'false'}
                    data-declared-source={!sourced && notSet ? 'true' : undefined}
                  >
                    <td>
                      {sourced ? (
                        <span>{f.caption}</span>
                      ) : (
                        <label htmlFor={inputId}>{f.caption}</label>
                      )}
                    </td>
                    <td>
                      {sourced ? (
                        <span data-testid={`official-estar-value-${f.key}`}>{f.value}</span>
                      ) : (
                        <input
                          id={inputId}
                          style={fieldInputStyle}
                          value={typed[f.key] ?? ''}
                          onChange={(e) => {
                            const v = e.target.value;
                            setTyped((t) => ({ ...t, [f.key]: v }));
                          }}
                          aria-describedby={`${inputId}-note`}
                        />
                      )}
                    </td>
                    <td style={{ color: 'var(--text-300)', fontSize: 11 }}>
                      {sourced ? (
                        sourceWords(f.source)
                      ) : (
                        <span id={`${inputId}-note`}>
                          {notSet ? (
                            <span
                              data-testid={`official-estar-not-set-${f.key}`}
                              style={{ display: 'block' }}
                            >
                              {notSet}
                            </span>
                          ) : null}
                          Entered for this export only · not stored
                        </span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </>
  );
}

// @vitest-environment jsdom
/** The mounted official exporter reaches the existing authorized Vault picker. */
import React from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { authService } from '@/services/portal/authService';
import { ATTACHMENT_MANIFEST_SEED } from '@shared/regulatory/estar-attachment-manifest';
import { OfficialEstarPanel, type OfficialEstarPanelProps } from '../OfficialEstarPanel';
import type { OfficialEstarType, OfficialEstarVariant } from '../../hooks/useEstarOfficialFields';
import { downloadBase64 } from '../../../v2/download';

const apiRequest = vi.hoisted(() => vi.fn());
vi.mock('@/lib/queryClient', async original => ({ ...(await original<typeof import('@/lib/queryClient')>()), apiRequest }));
vi.mock('../../../v2/download', async original => ({ ...(await original<typeof import('../../../v2/download')>()), downloadBase64: vi.fn(() => true) }));

const PROGRAM = { id: '11111111-1111-4111-8111-111111111111', code: 'DX-101', title: 'Diagnostic program' };
const OTHER = { id: '22222222-2222-4222-8222-222222222222', title: 'Another program' };
const DOC = '33333333-3333-4333-8333-333333333333';
const NEXT = '44444444-4444-4444-8444-444444444444';
const SHA = 'a'.repeat(64);
const COVER = 'root.CoverLetter.CLAddAttachment110';
const CLINICAL = 'root.ClinicalStudies.AddAttachment';
const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json' } });
const catalog = (type = '510k', variant = 'device') => ({ descriptorId: `${type}-${variant}`, type, variant, templateVersion: '6.1', slots: [
  { somPath: COVER, field: 'CLAddAttachment110', description: 'Administrative Documentation | Cover Letter', chapters: ['/CHAPTER 1/CH1.01/'], singleAttachment: 'Only a single cover letter is needed.' },
  { somPath: CLINICAL, field: 'AddAttachment', description: 'Clinical evidence', chapters: ['/CHAPTER 3/CH3.01/'], singleAttachment: null },
] });
const searchPage = (offset = 0, changes: Record<string, unknown> = {}) => ({ data: { query: 'summary', total: 26, limit: 25, offset, results: [{
  id: offset ? NEXT : DOC, title: offset ? 'Later evidence' : 'Approved clinical summary', version: '2.0', current: true,
  contentHash: SHA, snippet: null, ...changes,
}] } });
type Posted = { attachments?: Array<{ slot: string; source: { kind: string; documentId: string } }> };
const exported = (body: Posted, extra: Record<string, unknown> = {}) => json({ governed: true, officialEstarPdf: true, erasedFields: [],
  downloadable_output_ref: { encoding: 'base64', mime_type: 'application/pdf', filename: 'official.pdf', data: 'JVBERi0=' },
  ...(body.attachments?.length ? { attachmentReport: { requested: body.attachments.length,
    attached: body.attachments.map(a => ({ ...a, fileName: 'Clinical-summary.pdf', sha256: SHA, byteLength: 128, chapter: a.slot === COVER ? '/CHAPTER 1/CH1.01/' : '/CHAPTER 3/CH3.01/' })),
    refused: [], manifest: ATTACHMENT_MANIFEST_SEED + body.attachments.map(a => `<<Clinical-summary.pdf|${a.slot === COVER ? '/CHAPTER 1/CH1.01/' : '/CHAPTER 3/CH3.01/'}>>`).join('') } } : {}), ...extra,
});
const deferred = () => { let resolve!: (r: Response) => void; const promise = new Promise<Response>(done => { resolve = done; }); return { promise, resolve }; };
let slotReply: (type: string, variant: string) => Response | Promise<Response>;
let searchReply: (path: string) => Response | Promise<Response>;
let postReply: (body: Posted) => Response | Promise<Response>;
let posted: Posted[];

beforeEach(() => {
  authService.setToken('fixture-estar-author', { id: '7', organizationId: '1' }, 'fixture-estar-refresh', 3600);
  vi.mocked(downloadBase64).mockClear(); posted = [];
  slotReply = (type, variant) => json(catalog(type, variant));
  searchReply = path => json(searchPage(Number(new URL(path, 'https://fixture.invalid').searchParams.get('offset') ?? 0)));
  postReply = body => exported(body);
  apiRequest.mockReset().mockImplementation(async (_method: string, path: string) => {
    const url = new URL(path, 'https://fixture.invalid');
    if (url.pathname.endsWith('/attachment-slots')) return slotReply(url.searchParams.get('type')!, url.searchParams.get('variant')!);
    if (url.pathname === `/api/c2c/project-vault/${PROGRAM.id}/search` || url.pathname === `/api/c2c/project-vault/${OTHER.id}/search`) return searchReply(path);
    throw new Error(`Unexpected fixture request ${path}`);
  });
  vi.stubGlobal('fetch', vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = new URL(String(input), 'https://fixture.invalid');
    if (url.pathname.endsWith('/readiness')) return json({ ready: true, templateAvailable: true, fieldMapPopulated: true, blockers: [] });
    if (url.pathname.endsWith('/official-fields')) return json({ descriptorId: 'official', type: url.searchParams.get('type'), variant: url.searchParams.get('variant'), mappedCount: 0, sourcedCount: 0, fields: [] });
    if (url.pathname.endsWith('/official') && init?.method === 'POST') { const body = JSON.parse(String(init.body)) as Posted; posted.push(body); return postReply(body); }
    return json({});
  }));
});
afterEach(() => { cleanup(); authService.endSession(null); vi.unstubAllGlobals(); });
const props = (): OfficialEstarPanelProps => ({ program: PROGRAM, variant: 'device', type: '510k' });
const generate = () => screen.getByRole('button', { name: /Generate official eSTAR/ });
const add = () => fireEvent.click(screen.getByRole('button', { name: 'Add Vault attachment' }));
const row = (n = 1) => screen.getByRole('group', { name: `Attachment ${n}` });
async function ready(p = props()) { const view = render(<OfficialEstarPanel {...p} />); await waitFor(() => expect(generate()).toHaveProperty('disabled', false)); return view; }
async function choose(n = 1, slot = COVER) {
  const group = within(row(n));
  fireEvent.change(await group.findByLabelText('FDA destination'), { target: { value: slot } });
  fireEvent.change(group.getByLabelText("Search this project's Vault"), { target: { value: 'summary' } });
  fireEvent.click(group.getByRole('button', { name: 'Search Vault' }));
  fireEvent.click(await group.findByRole('button', { name: 'Select document' }));
}

describe('optional explicit official eSTAR attachments', () => {
  it('starts with no attachment rows or metadata/source reads, and retains export without attachments', async () => {
    await ready(); expect(screen.queryByRole('group', { name: 'Attachment 1' })).toBeNull();
    expect(apiRequest).not.toHaveBeenCalled(); fireEvent.click(generate());
    await waitFor(() => expect(posted).toHaveLength(1)); expect(posted[0]).not.toHaveProperty('attachments');
  });
  it('blocks an incomplete row while destinations load, and removal restores export without attachments', async () => {
    const pending = deferred(); slotReply = () => pending.promise;
    await ready(); add(); expect(generate()).toHaveProperty('disabled', true);
    expect(await screen.findByText('Reading FDA attachment destinations…')).toBeTruthy();
    fireEvent.click(within(row()).getByRole('button', { name: 'Remove attachment' }));
    expect(generate()).toHaveProperty('disabled', false);
    await act(async () => { pending.resolve(json(catalog())); });
    expect(screen.queryByRole('group', { name: 'Attachment 1' })).toBeNull();
  });
  it.each([['510k', 'device'], ['de_novo', 'ivd'], ['pma', 'ivd']] as const)('selects exact program-scoped versions and posts explicit destinations for %s/%s', async (type, variant) => {
    await ready({ ...props(), type, variant }); add(); await choose();
    expect(row().textContent).toContain('2.0'); expect(row().textContent).toContain(SHA);
    await waitFor(() => expect(generate()).toHaveProperty('disabled', false)); fireEvent.click(generate());
    await screen.findByTestId('official-estar-attachment-receipts');
    expect(posted[0].attachments).toEqual([{ slot: COVER, source: { kind: 'vault_document', documentId: DOC } }]);
    expect(JSON.stringify(posted[0])).not.toContain('expectedSha256');
    expect(screen.getByTestId('official-estar-attachment-receipts').textContent).toContain('Clinical-summary.pdf');
    expect(screen.getByTestId('official-estar-attachment-receipts').textContent).toContain('/CHAPTER 1/CH1.01/');
    expect(screen.getByTestId('official-estar-attachment-receipts').textContent).toContain(SHA);
    expect(screen.getByTestId('official-estar-attachment-receipts').textContent).toContain(DOC);
    expect(apiRequest).toHaveBeenCalledWith('GET', `/api/c2c/project-vault/${PROGRAM.id}/search?q=summary&limit=25`);
    expect(vi.mocked(downloadBase64)).toHaveBeenCalledTimes(1);
  });
  it('uses the existing picker pages instead of hiding matches after the first page', async () => {
    await ready(); add(); const group = within(row());
    fireEvent.change(await group.findByLabelText('FDA destination'), { target: { value: CLINICAL } });
    fireEvent.change(group.getByLabelText("Search this project's Vault"), { target: { value: 'summary' } });
    fireEvent.click(group.getByRole('button', { name: 'Search Vault' }));
    await group.findByText('Approved clinical summary'); fireEvent.click(group.getByRole('button', { name: 'Next Vault results' }));
    await group.findByText('Later evidence'); fireEvent.click(group.getByRole('button', { name: 'Select document' }));
    await waitFor(() => expect(generate()).toHaveProperty('disabled', false)); fireEvent.click(generate());
    await waitFor(() => expect(posted[0]?.attachments?.[0].source.documentId).toBe(NEXT));
  });
  it('blocks duplicate single-file destinations and preserves a deliberate change or removal', async () => {
    await ready(); add(); await choose(); add(); await choose(2);
    expect(generate()).toHaveProperty('disabled', true); expect(screen.getByTestId('official-estar-attachments').textContent).toContain('Only a single cover letter is needed.');
    fireEvent.change(within(row(2)).getByLabelText('FDA destination'), { target: { value: CLINICAL } });
    expect(generate()).toHaveProperty('disabled', false);
    fireEvent.click(within(row(2)).getByRole('button', { name: 'Remove attachment' }));
    expect(generate()).toHaveProperty('disabled', false);
    fireEvent.click(within(row()).getByRole('button', { name: 'Change document' })); expect(generate()).toHaveProperty('disabled', true);
  });
  it('caps even queued Add activations at the server’s 150-assignment limit', async () => {
    await ready(); const button = screen.getByRole('button', { name: 'Add Vault attachment' });
    act(() => { for (let index = 0; index < 155; index += 1) fireEvent.click(button); });
    expect(screen.getAllByRole('group', { name: /^Attachment \d+$/ })).toHaveLength(150);
    expect(button).toHaveProperty('disabled', true);
    expect(screen.getByText(/Up to 150 Vault attachments/)).toBeTruthy();
  });
});

describe('attachment source and catalog refusals', () => {
  it('rejects a selectable Vault result without a recorded hash', async () => {
    searchReply = () => json(searchPage(0, { contentHash: null })); await ready(); add(); await choose();
    expect(await screen.findByText(/Choose a current Vault version with a valid document id and recorded SHA-256/)).toBeTruthy();
    expect(generate()).toHaveProperty('disabled', true); expect(posted).toHaveLength(0);
  });
  it('keeps earlier versions unavailable in the reused picker', async () => {
    searchReply = () => json(searchPage(0, { current: false })); await ready(); add(); const group = within(row());
    fireEvent.change(group.getByLabelText("Search this project's Vault"), { target: { value: 'summary' } });
    fireEvent.click(group.getByRole('button', { name: 'Search Vault' }));
    expect(await group.findByRole('button', { name: 'Select document' })).toHaveProperty('disabled', true);
    expect(generate()).toHaveProperty('disabled', true);
  });
  it.each(['wrong type', 'wrong variant', 'missing template version', 'duplicate slot'] as const)('rejects a successful catalog with %s instead of offering unverified destinations', async kind => {
    const body = catalog();
    slotReply = () => json(kind === 'wrong type' ? { ...body, type: 'pma' } : kind === 'wrong variant' ? { ...body, variant: 'ivd' }
      : kind === 'missing template version' ? { ...body, templateVersion: null } : { ...body, slots: [body.slots[0], body.slots[0]] });
    await ready(); add(); await screen.findByRole('button', { name: 'Retry attachment destinations' });
    expect(generate()).toHaveProperty('disabled', true); expect(screen.queryByRole('option', { name: /Cover Letter/ })).toBeNull();
  });
  it('retries a failed slot read without discarding the row or treating failure as empty', async () => {
    slotReply = () => json({ message: 'Template metadata unavailable.' }, 503); await ready(); add();
    await screen.findByRole('button', { name: 'Retry attachment destinations' });
    slotReply = (type, variant) => json(catalog(type, variant));
    fireEvent.click(await screen.findByRole('button', { name: 'Retry attachment destinations' }));
    await within(row()).findByRole('option', { name: /Cover Letter/ }); expect(generate()).toHaveProperty('disabled', true);
  });
  it('describes a verified catalog with no destinations and permits removing the optional row', async () => {
    slotReply = () => json({ ...catalog(), slots: [] }); await ready(); add();
    await screen.findByText(/This template has no attachment destinations/);
    expect(generate()).toHaveProperty('disabled', true);
    fireEvent.click(within(row()).getByRole('button', { name: 'Remove attachment' }));
    expect(generate()).toHaveProperty('disabled', false);
  });
  it('renders actual server refusal reasons and keeps the chosen version reviewable', async () => {
    postReply = () => json({ error: 'ESTAR_NOT_PRODUCIBLE', blockers: ['The selected version is no longer current.'], attachmentReport: {
      requested: 1, attached: [], refused: [{ slot: COVER, reasons: ['The selected version is no longer current.'] }], manifest: null,
    } }, 422);
    await ready(); add(); await choose(); fireEvent.click(generate());
    const refused = await screen.findByTestId('official-estar-attachment-refusals');
    expect(refused.textContent).toContain('The selected version is no longer current.');
    expect(row().textContent).toContain('Approved clinical summary'); expect(vi.mocked(downloadBase64)).not.toHaveBeenCalled();
  });
});

describe('attachment request ownership', () => {
  it.each(['program', 'pathway', 'variant', 'session'] as const)('resets selected rows when the %s changes', async change => {
    const view = await ready(); add(); await choose();
    if (change === 'session') act(() => { authService.setToken('fixture-other-author', { id: '8', organizationId: '1' }, 'fixture-other-refresh', 3600); });
    else view.rerender(<OfficialEstarPanel {...props()} program={change === 'program' ? OTHER : PROGRAM}
      type={(change === 'pathway' ? 'pma' : '510k') as OfficialEstarType} variant={(change === 'variant' ? 'ivd' : 'device') as OfficialEstarVariant} />);
    expect(screen.queryByRole('group', { name: 'Attachment 1' })).toBeNull();
    expect(screen.queryByText('Approved clinical summary')).toBeNull();
  });
  it('disables assignment edits while an attachment-bearing export is pending', async () => {
    const pending = deferred(); postReply = () => pending.promise;
    await ready(); add(); await choose(); fireEvent.click(generate());
    await waitFor(() => expect(posted).toHaveLength(1));
    expect(within(row()).getByLabelText('FDA destination')).toHaveProperty('disabled', true);
    expect(within(row()).getByRole('button', { name: 'Change document' })).toHaveProperty('disabled', true);
    expect(within(row()).getByRole('button', { name: 'Remove attachment' })).toHaveProperty('disabled', true);
    expect(screen.getByRole('button', { name: 'Add Vault attachment' })).toHaveProperty('disabled', true);
    await act(async () => { pending.resolve(exported(posted[0])); });
  });
  it('does not expose attachment controls for PreSTAR preparation', async () => {
    render(<OfficialEstarPanel {...props()} type="q_sub" />);
    await screen.findByRole('button', { name: /Prepare PreSTAR fields/ });
    expect(screen.queryByRole('button', { name: 'Add Vault attachment' })).toBeNull();
    expect(apiRequest).not.toHaveBeenCalled();
  });
});
